using namespace std;
int main() {
    int n;
    scanf("%d", &n);
    vector<long long> s(n), t(n);
    for (auto &x : s) scanf("%lld", &x);
    for (auto &x : t) scanf("%lld", &x);
    // y[i] = (-1)^i (t[i]-s[i]); one operation adds a constant to an even-length block of y.
    vector<long long> z(n + 1);
    long long prev = 0;
    for (int i = 0; i < n; i++) {
        long long y = i % 2 == 0 ? t[i] - s[i] : s[i] - t[i];
        z[i] = y - prev;
        prev = y;
    }
    z[n] = -prev;
    long long answer = 0;
    // Boundaries of one operation share parity: even ones open with +1, odd ones with -1.
    for (int parity = 0; parity < 2; parity++) {
        long long prefix = 0;
        for (int i = parity; i <= n; i += 2) {
            prefix += z[i];
            if ((parity == 0 && prefix < 0) || (parity == 1 && prefix > 0)) { puts("-1"); return 0; }
            answer += max(0LL, z[i]);
        }
        if (prefix) { puts("-1"); return 0; }
    }
    printf("%lld\n", answer);
}

import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] s = new long[n], t = new long[n];
        for (int i = 0; i < n; i++) s[i] = nextLong();
        for (int i = 0; i < n; i++) t[i] = nextLong();
        // y[i] = (-1)^i (t[i]-s[i]); one operation adds a constant to an even-length block of y.
        long[] z = new long[n + 1];
        long prev = 0;
        for (int i = 0; i < n; i++) {
            long y = i % 2 == 0 ? t[i] - s[i] : s[i] - t[i];
            z[i] = y - prev;
            prev = y;
        }
        z[n] = -prev;
        long answer = 0;
        // Boundaries of one operation share parity: even ones open with +1, odd ones with -1.
        for (int parity = 0; parity < 2; parity++) {
            long prefix = 0;
            for (int i = parity; i <= n; i += 2) {
                prefix += z[i];
                if ((parity == 0 && prefix < 0) || (parity == 1 && prefix > 0)) { System.out.println(-1); return; }
                answer += Math.max(0, z[i]);
            }
            if (prefix != 0) { System.out.println(-1); return; }
        }
        System.out.println(answer);
    }
}

